using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigurationResourceProvider
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "Application Settings",
        Description = "Returns the current application configuration")]
    public static string GetAppSettings()
    {
        return """
            {
              "appName": "McpHttpServer",
              "version": "1.0.0",
              "environment": "production",
              "features": {
                "logging": true,
                "metrics": true,
                "tracing": false
              }
            }
            """;
    }

    [McpServerResource(UriTemplate = "config://app/endpoints",
        Name = "API Endpoints",
        Description = "Returns the list of available API endpoints")]
    public static string GetEndpoints()
    {
        return """
            {
              "endpoints": [
                { "path": "/api/health", "method": "GET" },
                { "path": "/api/status", "method": "GET" }
              ]
            }
            """;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpHttpServer;

[McpServerToolType]
public static class Tools
{
    [McpServerTool, Description("Gets the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is running. Uptime: {Environment.TickCount64 / 1000}s";
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

